try (java.io.InputStream is1 = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(grid_png));
     java.io.InputStream is2 = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(grid_jpeg))) {

    java.util.List<java.awt.image.BufferedImage> thumbnails = net.coobird.thumbnailator.Thumbnails.fromInputStreams(java.util.Arrays.asList(is1, is2))
        .forceSize(50, 50)
        .asBufferedImages();

    assert thumbnails != null && thumbnails.size() == 2 : "Expected 2 thumbnails, got " + (thumbnails == null ? "null" : thumbnails.size());

    java.awt.image.BufferedImage thumb1 = thumbnails.get(0);
    java.awt.image.BufferedImage thumb2 = thumbnails.get(1);

    assert thumb1.getWidth() == 50 && thumb1.getHeight() == 50 : "Expected first thumbnail to be 50x50, got " + thumb1.getWidth() + "x" + thumb1.getHeight();
    assert thumb2.getWidth() == 50 && thumb2.getHeight() == 50 : "Expected second thumbnail to be 50x50, got " + thumb2.getWidth() + "x" + thumb2.getHeight();

    System.out.println("__CHECK__ fromInputStreams " + thumbnails.size() + " images, first is " + thumb1.getWidth() + "x" + thumb1.getHeight());
} catch (java.io.IOException e) {
    throw new RuntimeException("Failed to read input streams or process thumbnails", e);
}
